# Quick scan of all files in this directory tree
def scan_files(path, max_depth=2, current_depth=0):
    if current_depth > max_depth:
        return []
    results = []
    try:
        entries = os.listdir(path)
        for e in entries:
            if e.startswith('.') or e == '__pycache__':
                continue
            epath = os.path.join(path, e)
            if os.path.isfile(epath):
                results.append(e)
            elif os.path.isdir(epath):
                results.extend(scan_files(epath, max_depth, current_depth+1))
    except:
        pass
    return results

